def mark_existing_types_as_user_provided(apps, schema_editor):
    """Treat every already-classified pin/wiki as deliberately classified.

    Until now the only way a row got a non-default ``pin_type`` was a human
    picking one out of the detail-pin dialog's Type select, so automatic
    classification (which this migration's new flag gates) must leave all of
    them alone. Rows still on the ``location`` default stay unflagged and
    remain eligible for auto-classification.
    """
    for model_name in ("Pin", "Wiki"):
        model = apps.get_model("dashboard", model_name)
        model.objects.exclude(pin_type="location").update(pin_type_is_user_provided=True)


def unmark_all(apps, schema_editor):
    """Reverse of :func:`mark_existing_types_as_user_provided`."""
    for model_name in ("Pin", "Wiki"):
        apps.get_model("dashboard", model_name).objects.update(pin_type_is_user_provided=False)


def backfill_intro_seen(apps, schema_editor):
    """Mark the new-user map dialog as already seen for every existing profile.

    ``map_pin_suggestions_intro_seen`` defaults to False so it only appears
    for accounts created after this migration - existing users should never
    be nagged with a "new" onboarding dialog on their next map visit.
    """
    Profile = apps.get_model("dashboard", "Profile")
    Profile.objects.update(map_pin_suggestions_intro_seen=True)


